import socket,sys,time
s=socket.create_connection(('127.0.0.1',4555)); s.settimeout(1)
def rd(t=5):
    out=b''; end=time.time()+t
    while time.time()<end:
        try: d=s.recv(65536)
        except socket.timeout: continue
        if not d: break
        out+=d
    return out.decode('utf8','replace')
def wr(x): s.sendall((x+'\n').encode())
if len(sys.argv)>1 and sys.argv[1]=='read':
    print(rd(int(sys.argv[2]) if len(sys.argv)>2 else 5))
else:
    for c in sys.argv[1:]:
        wr(c); time.sleep(0.5)
    print(rd(int(__import__('os').environ.get('W','8'))))
EOF
